import { Injectable } from "@nestjs/common";
import type { CalendarWindowDto } from "#/modules/event/schema/dto/calendar-window.dto.ts";
import type { OccurrenceCollectionDto } from "#/modules/event/schema/dto/occurrence-collection.dto.ts";
import { ListOccurrencesUseCase } from "#/modules/event/features/calendar/use-cases/list-occurrences.repository.ts";

/**
 * The Calendar contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class EventCalendarService {
  abstract listOccurrences(input: CalendarWindowDto): Promise<OccurrenceCollectionDto>;
}

@Injectable()
export class EventCalendarServiceImpl extends EventCalendarService {
  constructor(private readonly listOccurrencesUseCase: ListOccurrencesUseCase) {
    super();
  }

  listOccurrences(input: CalendarWindowDto): Promise<OccurrenceCollectionDto> {
    return this.listOccurrencesUseCase.execute(input);
  }
}
